#pragma once
#include <cstdint>
#include <glm/glm.hpp>
#include <glm/gtc/quaternion.hpp>
#include <vector>

#include "../Physics/Physics.hpp"
#include "WorldGenerator.hpp"

namespace bibo {
namespace world {
/**
 * Everything that grows or lies on the ground: trees, bushes, grass, mushrooms,
 * stones, ... The meshes are generated by the game (VegetationMeshes), every
 * model is drawn instanced.
 */
enum class Model : std::uint8_t {
  SPRUCE_TALL,
  SPRUCE_WIDE,
  SPRUCE_YOUNG,
  PINE,
  BUSH,
  JUNIPER,
  FERN,
  GRASS,
  GRASS_DRY,
  MUSHROOM_RED,
  MUSHROOM_BROWN,
  MUSHROOM_GLOW,
  STONE_ROUND,
  STONE_FLAT,
  STONE_SHARP,
  STONE_STANDING,
  LOG,
  STUMP,
  COUNT
};
constexpr int MODEL_COUNT = static_cast<int>(Model::COUNT);

/**
 * Small things are only placed (and drawn) close to the camera, large ones
 * everywhere
 */
enum class Layer {
  LARGE,  // trees, bushes, boulders, logs
  SMALL   // grass, ferns, mushrooms, pebbles
};

/**
 * A placed model (48 bytes, uploaded to the graphics card as it is)
 */
struct Instance {
  glm::vec4 positionScale;  // position of the foot, uniform scale
  glm::vec4 rotation;       // quaternion x, y, z, w
  // x: tint (-1 to 1, color variation), y: random number (0 to 1), z, w: unused
  glm::vec4 parameters;
  Model model() const {
    return static_cast<Model>(static_cast<int>(parameters.z));
  }
};

/**
 * Columns of the world (CHUNK_SIZE wide, all the way up) are the unit of the
 * scattering
 */
struct ColumnKey {
  int x = 0, z = 0;
  bool operator==(const ColumnKey&) const = default;
};

struct ColumnKeyHash {
  std::size_t operator()(const ColumnKey& key) const {
    return static_cast<std::size_t>(key.x * 73856093) ^
           static_cast<std::size_t>(key.z * 83492791);
  }
};

/**
 * Places the models of a layer in a column of the world. Deterministic: a
 * column always gets the same instances, no matter when it is scattered. Trees
 * grow on the slopes of the track and in the forest, never on the floor of the
 * track; the cave has glowing mushrooms; nothing grows in the sea.
 * @param collision Gets the trunks of the trees and the boulders (nullptr: not
 * needed)
 */
std::vector<Instance> scatter(
    const WorldGenerator& world, ColumnKey column, Layer layer,
    std::vector<physics::ShapePart>* collision = nullptr);

/**
 * Height of the model at scale 1 (e.g. for the bounding sphere)
 */
float modelHeight(Model model);
/**
 * Radius of the model at scale 1 around its vertical axis
 */
float modelRadius(Model model);
}  // namespace world
}  // namespace bibo
